YEP_X_Autosave.MsgGradientCode:
"var textWidth = this.textWidthEx(this.message());
var half = this.textPadding() + Math.ceil(textWidth / 2);
var height = this.lineHeight();
var color1 = Yanfly.Param.AutosaveMsgColor1;
var color2 = Yanfly.Param.AutosaveMsgColor2;
this.contents.gradientFillRect(0, 0, half, height, color1, color2);
this.contents.gradientFillRect(half, 0, this.width - half, height, color2, color1);"
